fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cell: i32 = w / 64;
    let rows: i32 = h / cell;
    let mut cur = [0; 64];
    let mut next = [0; 64];
    cur[32] = 1;
    let shade: i32 = 120 + (t / 2) % 100;
    let color: i32 = shade * 256 + 40 + shade * 65536 / 4;
    host::display::clear(0x000000);
    let mut r: i32 = 0;
    while r < rows {
        let mut i: i32 = 0;
        while i < 64 {
            if cur[i] == 1 {
                host::display::fill_rect(i * cell, r * cell, cell, cell, color);
            }
            i = i + 1;
        }
        i = 0;
        while i < 64 {
            let left: i32 = if i == 0 { 0 } else { cur[i - 1] };
            let right: i32 = if i == 63 { 0 } else { cur[i + 1] };
            next[i] = left ^ right;
            i = i + 1;
        }
        i = 0;
        while i < 64 {
            cur[i] = next[i];
            i = i + 1;
        }
        r = r + 1;
    }
    host::display::present();
}
